## 4.3 Main mixer contract

**File:** `contracts/PrivateCrypMix.sol`
```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "./interfaces/IERC20.sol";
import "./interfaces/IYieldVault.sol";
import "./interfaces/IConnextRouter.sol";
import "./interfaces/IVerifier.sol";

contract PrivateCrypMix {
    // ======== Admin ========
    address public owner;
    modifier onlyOwner() {
        require(msg.sender == owner, "NOT_OWNER");
        _;
    }

    constructor(address _verifier, address _yieldVault, address _connextRouter, bytes32 _polygonDomain) {
        owner = msg.sender;
        verifier = IVerifier(_verifier);
        yieldVault = IYieldVault(_yieldVault);
        connextRouter = IConnextRouter(_connextRouter);
        polygonDomain = _polygonDomain;
    }

    // ======== Config ========
    IVerifier public verifier;
    IYieldVault public yieldVault;
    IConnextRouter public connextRouter;
    bytes32 public polygonDomain;

    uint256 public lockDelaySeconds;

    // Fixed-size deposit amounts per asset
    mapping(address => uint256) public fixedDepositAmount;

    // Active assets list (for UI convenience)
    address[] public supportedAssets;
    mapping(address => bool) public isSupportedAsset;

    // ======== Privacy storage ========
    // commitments -> timestamp when deposited (used for lock enforcement)
    mapping(bytes32 => uint64) public commitmentTimestamp;

    // nullifierHash -> spent (double-spend prevention)
    mapping(bytes32 => bool) public nullifierSpent;

    // Yield accounting:
    // Each commitment gets a record for the yield vault position.
    // We avoid storing per-user identities; we only store commitment keyed data.
    struct DepositPosition {
        address asset;
        uint256 amount; // fixed deposit amount in underlying
        uint256 shares; // yieldVault shares/position reference
    }

    mapping(bytes32 => DepositPosition) public positions;

    // ======== Events ========
    event Deposit(address indexed asset, bytes32 indexed commitment, uint256 amount, uint256 shares);
    event WithdrawalQueued(
        address indexed asset,
        bytes32 indexed commitment,
        bytes32 indexed nullifierHash,
        uint64 depositedAt,
        address destinationAddress,
        bytes32 destinationDomain,
        uint256 amount
    );

    event AdminSetLockDelay(uint256 lockDelaySeconds);
    event AdminSetFixedDeposit(address indexed asset, uint256 amount);
    event OwnershipTransferred(address indexed from, address indexed to);
    event VerifierUpdated(address indexed verifier);

    function transferOwnership(address newOwner) external onlyOwner {
        require(newOwner != address(0), "ZERO");
        emit OwnershipTransferred(owner, newOwner);
        owner = newOwner;
    }

    function setLockDelaySeconds(uint256 _lockDelaySeconds) external onlyOwner {
        lockDelaySeconds = _lockDelaySeconds;
        emit AdminSetLockDelay(_lockDelaySeconds);
    }

    function setVerifier(address _verifier) external onlyOwner {
        verifier = IVerifier(_verifier);
        emit VerifierUpdated(_verifier);
    }

    function addSupportedAsset(address asset, uint256 fixedAmount) external onlyOwner {
        require(asset != address(0), "ZERO_ASSET");
        require(!isSupportedAsset[asset], "ALREADY");
        isSupportedAsset[asset] = true;
        fixedDepositAmount[asset] = fixedAmount;
        supportedAssets.push(asset);
        emit AdminSetFixedDeposit(asset, fixedAmount);
    }

    // ======== Core: Deposit ========
    /**
     * @param commitment Hash of (asset, amount, secret, etc) generated client-side.
     * Enforce fixed size deposits to maintain anonymity set uniformity.
     */
    function deposit(address asset, bytes32 commitment) external {
        require(isSupportedAsset[asset], "UNSUPPORTED_ASSET");
        require(commitmentTimestamp[commitment] == 0, "COMMITMENT_EXISTS");

        uint256 amount = fixedDepositAmount[asset];
        require(amount > 0, "BAD_AMOUNT");

        // Transfer underlying into this contract
        require(IERC20(asset).transferFrom(msg.sender, address(this), amount), "TRANSFER_FAIL");

        // Deposit into yield vault
        // shares identifies position (Aave adapter should return a reference)
        uint256 shares = yieldVault.deposit(asset, amount);

        commitmentTimestamp[commitment] = uint64(block.timestamp);
        positions[commitment] = DepositPosition({
            asset: asset,
            amount: amount,
            shares: shares
        });

        emit Deposit(asset, commitment, amount, shares);
    }

    // ======== Core: Withdrawal (cross-chain) ========
    /**
     * @param proof zkSNARK proof bytes (from circuit)
     * @param commitment commitment hash used at deposit time
     * @param nullifierHash prevents double spends for that commitment
     * @param destinationDomain Connext domain id for destination chain
     * @param destinationAddress recipient address on destination chain (same as user input)
     * @param destinationAsset asset to send on destination chain (must match deposit asset)
     *
     * @dev The contract:
     * - verifies proof
     * - checks lockDelay
     * - checks nullifier not spent
     * - withdraws yield position from yieldVault
     * - calls Connext to send tokens cross-chain
     *
     * IMPORTANT: For privacy, proof verification should link commitment and nullifier without revealing identity.
     */
    function withdraw(
        bytes calldata proof,
        bytes32 commitment,
        bytes32 nullifierHash,
        bytes32 destinationDomain,
        address payable destinationAddress,
        address destinationAsset
    ) external payable {
        require(commitmentTimestamp[commitment] != 0, "COMMITMENT_UNKNOWN");
        require(!nullifierSpent[nullifierHash], "NULLIFIER_SPENT");

        DepositPosition memory pos = positions[commitment];
        require(pos.asset == destinationAsset, "ASSET_MISMATCH");

        uint64 depositedAt = commitmentTimestamp[commitment];
        require(block.timestamp >= depositedAt + lockDelaySeconds, "LOCK_NOT_PASSED");

        // Verify zk proof (dev uses MockVerifier; replace with real zk verifier)
        bool ok = verifier.verifyProof(proof, commitment, nullifierHash);
        require(ok, "BAD_PROOF");

        nullifierSpent[nullifierHash] = true;

        // Withdraw underlying+yield from yield vault
        uint256 underlyingReceived = yieldVault.withdraw(destinationAsset, pos.shares);

        emit WithdrawalQueued(
            destinationAsset,
            commitment,
            nullifierHash,
            depositedAt,
            destinationAddress,
            destinationDomain,
            underlyingReceived
        );

        // Cross-chain send
        // IMPORTANT: Replace xcall signature with your real Connext router ABI.
        // `callData` placeholder set to 0.
        connextRouter.xcall(destinationDomain, msg.sender, destinationAsset, destinationAddress, underlyingReceived, 0);
        // NOTE: msg.sender passed as destinationAddress param in interface mismatch.
        // Replace with correct destinationAddress parameter mapping for Connext.
    }

    // ======== Views ========
    function getSupportedAssets() external view returns (address[] memory) {
        return supportedAssets;
    }

    function canWithdraw(bytes32 commitment) external view returns (bool) {
        uint64 ts = commitmentTimestamp[commitment];
        if (ts == 0) return false;
        return block.timestamp >= ts + lockDelaySeconds;
    }
}
```

> Note: The Connext `xcall` interface above is intentionally abstract. When you wire real Connext, you must update the interface and call.

