import { ethers } from "ethers";

/**
 * Commitment scheme (scaffold):
 * commitment = keccak256(abi.encode(asset, amount, secret))
 *
 * For real Tornado-style privacy, use the exact circuit's hashing scheme
 * and also produce nullifier = H(secret or nullifierSecret).
 */
export function makeCommitment(asset: string, amount: bigint, secret: string): string {
  const enc = ethers.AbiCoder.defaultAbiCoder().encode(
    ["address", "uint256", "bytes32"],
    [asset, amount, secret]
  );
  return ethers.keccak256(enc);
}

export function makeNullifierHash(secretNullifier: string): string {
  return ethers.keccak256(ethers.getBytes(secretNullifier));
}
```

