/**
 * Simple UX-only forecast.
 * Replace with on-chain rate math or vault APR from Aave.
 */
export function forecastYield(amount: bigint, aprBps: number, lockSeconds: number): bigint {
  // aprBps = basis points, e.g., 500 = 5% APR
  const apr = Number(aprBps) / 10000;
  const secondsPerYear = 365 * 24 * 60 * 60;
  const est = Number(amount.toString()) * apr * (lockSeconds / secondsPerYear);
  return BigInt(Math.floor(est));
}
